-- Task visibility (internal tasks never reach the customer) and Task Template v2 (linked to the Methodology).
-- Replaces all existing task templates with two new ones based on the SGS project:
--   "Standard Implementation" and "Implementation with Customization". Templates carry no dates.

ALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'external';
ALTER TABLE public.tasks DROP CONSTRAINT IF EXISTS tasks_visibility_check;
ALTER TABLE public.tasks ADD CONSTRAINT tasks_visibility_check CHECK (visibility IN ('external', 'internal'));

ALTER TABLE public.task_template_items ADD COLUMN IF NOT EXISTS resource text NOT NULL DEFAULT '';
ALTER TABLE public.task_template_items ADD COLUMN IF NOT EXISTS is_milestone boolean NOT NULL DEFAULT false;
ALTER TABLE public.task_template_items ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'external';
ALTER TABLE public.task_template_items DROP CONSTRAINT IF EXISTS task_template_items_visibility_check;
ALTER TABLE public.task_template_items ADD CONSTRAINT task_template_items_visibility_check CHECK (visibility IN ('external', 'internal'));
ALTER TABLE public.task_template_items ADD COLUMN IF NOT EXISTS methodology_phase_id text REFERENCES public.methodology_phases(id) ON DELETE SET NULL;
ALTER TABLE public.task_template_items ADD COLUMN IF NOT EXISTS deliverable_id text REFERENCES public.methodology_deliverables(id) ON DELETE SET NULL;

-- Remove the old templates (their items go with them)
DELETE FROM public.task_templates;

